import type { CanvasAssetVersion, CanvasPoint, SceneDocument, SceneVector3 } from '@nextmux/comic-core';
import type { DesktopComicCanvasState } from './nextmux-platform-protocol';

export interface ComicDirectorCameraSnapshot {
    readonly id?: string;
    readonly position: SceneVector3;
    /** Rotation is stored in degrees, like scene objects. */
    readonly rotation: SceneVector3;
    readonly lookAt?: SceneVector3;
    readonly fov: number;
}
/** Renderer-generated bytes only; this route never calls a model or reserves a payment. */
export interface SaveComicDirectorCaptureRequest {
    readonly workspaceRoot: string;
    readonly canvasId?: string;
    readonly expectedRevision: number;
    readonly sourceNodeId: string;
    /** Reuse this identifier for a retry of the same capture. */
    readonly captureId: string;
    readonly kind: 'image' | 'video';
    readonly mimeType: string;
    /** Supply exactly one of dataBase64 or uploadId. Large blobs use the chunk-upload RPCs. */
    readonly dataBase64?: string;
    readonly uploadId?: string;
    readonly scene: SceneDocument;
    readonly camera: ComicDirectorCameraSnapshot;
    readonly frame: number;
    readonly endFrame?: number;
    readonly title?: string;
    readonly position?: CanvasPoint;
}
/** 标记修图: a picture with the user's marks drawn over one ready image version. Local bytes only; never a model call. */
export interface SaveComicCanvasMarkedImageRequest {
    readonly workspaceRoot: string;
    readonly canvasId?: string;
    readonly expectedRevision: number;
    readonly sourceNodeId: string;
    readonly sourceVersionId: string;
    /** Reuse this identifier for a retry of the same marked picture. */
    readonly markId: string;
    /** Supply exactly one of dataBase64 or uploadId (purpose 'capture', image/png). */
    readonly dataBase64?: string;
    readonly uploadId?: string;
    readonly title?: string;
    readonly position?: CanvasPoint;
}
export interface ComicDirectorCaptureResult {
    readonly state: DesktopComicCanvasState;
    readonly nodeId: string;
    readonly version: CanvasAssetVersion;
}
export interface ImportComicDirectorModelRequest {
    readonly workspaceRoot: string;
    readonly name: string;
    readonly mimeType: string;
    readonly dataBase64?: string;
    readonly uploadId?: string;
}
export interface ComicDirectorModelImportResult {
    readonly uri: string;
    readonly kind: 'model' | 'splat';
    readonly mimeType: string;
    readonly byteLength: number;
    readonly sha256: string;
}
export interface BeginComicDirectorUploadRequest {
    readonly workspaceRoot: string;
    readonly uploadId?: string;
    readonly purpose: 'capture' | 'model';
    readonly byteLength: number;
    readonly mimeType: string;
    readonly name?: string;
}
export interface AppendComicDirectorUploadRequest {
    readonly workspaceRoot: string;
    readonly uploadId: string;
    readonly offset: number;
    readonly dataBase64: string;
}
export interface ComicDirectorUploadState {
    readonly uploadId: string;
    readonly offset: number;
    readonly byteLength: number;
}
